INSERT INTO public.quick_replies (id, user_id, text, "position", created_at) VALUES ('03579d79-6dd0-494c-aabf-7839b7662eed', 'f2be79d8-2d06-474d-9343-4b3e6ebba19f', 'Здравствуйте! Подскажите, удобно ли вам сейчас обсудить запись?', 0, '2026-05-10T17:29:26.319021+00:00');
