INSERT INTO public.quick_replies (id, user_id, text, "position", created_at) VALUES ('e2f13891-e8c9-4628-bbd0-fd084f82aa86', 'f2be79d8-2d06-474d-9343-4b3e6ebba19f', 'Спасибо за заявку! Подтверждаю — записал вас. Что-то ещё уточнить?', 1, '2026-05-10T17:29:26.319021+00:00');
